"""Agent-facing observation and action parsing helpers for MiniHack."""

from __future__ import annotations

import json
import re
from dataclasses import dataclass
from typing import Any


DIRECTION_RE = re.compile(
    r"\b(north|south|east|west|northeast|northwest|southeast|southwest)\b",
    re.IGNORECASE,
)


@dataclass(frozen=True)
class ParsedAction:
    action: dict[str, Any]
    invalid_parse: bool
    repaired: bool
    error: str | None = None

    def to_dict(self) -> dict[str, Any]:
        return {
            "action": self.action,
            "invalid_parse": self.invalid_parse,
            "repaired": self.repaired,
            "error": self.error,
        }


def _normalize_action(candidate: dict[str, Any]) -> dict[str, Any]:
    parsed = dict(candidate)
    if "kind" not in parsed and "direction" in parsed:
        parsed["kind"] = "move"
    return parsed


def _action_in_valid(candidate: dict[str, Any], valid_actions: list[dict[str, Any]]) -> bool:
    normalized = _normalize_action(candidate)
    for valid in valid_actions:
        if valid == normalized:
            return True
    return False


def parse_action_text(raw_text: Any, valid_actions: list[dict[str, Any]] | None = None) -> ParsedAction:
    valid = valid_actions or [{"kind": "wait"}]
    text = raw_text if isinstance(raw_text, str) else json.dumps(raw_text)
    candidates: list[dict[str, Any]] = []
    try:
        parsed = json.loads(text)
        if isinstance(parsed, dict):
            if "action" in parsed and isinstance(parsed["action"], dict):
                candidates.append(dict(parsed["action"]))
            else:
                candidates.append(dict(parsed))
        elif isinstance(parsed, list) and parsed and isinstance(parsed[0], dict):
            candidates.append(dict(parsed[0]))
    except json.JSONDecodeError:
        pass

    lowered = text.lower()
    if "pickup" in lowered or "pick up" in lowered:
        candidates.append({"kind": "pickup"})
    if "wait" in lowered:
        candidates.append({"kind": "wait"})
    if "attack" in lowered:
        direction_match = DIRECTION_RE.search(text)
        if direction_match:
            candidates.append({"kind": "attack", "direction": direction_match.group(1).lower()})
        else:
            candidates.append({"kind": "attack", "direction": "north"})
    direction_match = DIRECTION_RE.search(text)
    if direction_match:
        candidates.append({"kind": "move", "direction": direction_match.group(1).lower()})

    for candidate in candidates:
        normalized = _normalize_action(candidate)
        if _action_in_valid(normalized, valid):
            return ParsedAction(action=normalized, invalid_parse=False, repaired=False)

    return ParsedAction(action=dict(valid[0]), invalid_parse=True, repaired=True, error="no_valid_action_found")


def format_agent_observation(readout: dict[str, Any], *, objective: str | None = None) -> dict[str, Any]:
    public = readout.get("public") or {}
    private = readout.get("private") or {}
    profile = readout.get("profile", "unknown")
    lines = [
        objective or "Navigate the MiniHack symbolic grid: reach goals, solve box puzzles, or clear combat corridors.",
        "",
        "ASCII map legend: @ player, > goal, * target, O boulder, M monster, ~ lava, # wall.",
        f"Profile: {profile}",
        "",
        str(readout.get("ascii", "")),
        "",
        f"Player: {json.dumps(public.get('player'))}",
        f"Inventory: {json.dumps(public.get('inventory', []))}",
        f"Reward total: {float(private.get('total_reward', 0.0)):.2f}",
        f"Step: {private.get('step_index', 0)}",
        f"Valid actions: {json.dumps(readout.get('valid_actions', []))}",
    ]
    observation_text = "\n".join(lines)
    return {"observation_text": observation_text, "readout": readout}

"""Checkpoint restore report helper for MiniHack gold HTTP lane."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any


@dataclass
class RestoreReport:
    bytes: int
    wall_ms: float
    nev_events_restored: int

    def to_dict(self) -> dict[str, Any]:
        return {
            "bytes": self.bytes,
            "wall_ms": self.wall_ms,
            "nev_events_restored": self.nev_events_restored,
        }

"""FastAPI service for the Python MiniHack gold lane."""

from __future__ import annotations

import base64
import uuid
from dataclasses import dataclass, field
from typing import Any

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

from core.checkpoint import RestoreReport
from engine import MiniHackEngine
from scenarios import run_scenario
from task_resolve import resolve_task


class ScenarioRequest(BaseModel):
    task: dict[str, Any]


class RolloutRequest(BaseModel):
    task: dict[str, Any] | None = None
    seed: int | None = None


class StepRequest(BaseModel):
    action: dict[str, Any] | str


class RestoreRequest(BaseModel):
    blob: str


class SimulateRequest(BaseModel):
    blob: str
    sequences: list[list[dict[str, Any] | str]]


@dataclass
class RolloutSession:
    rollout_id: str
    engine: MiniHackEngine
    checkpoints: dict[str, bytes] = field(default_factory=dict)


def create_app() -> FastAPI:
    app = FastAPI(title="GameBench MiniHack Python Gold", version="0.1.0")
    sessions: dict[str, RolloutSession] = {}

    @app.get("/health")
    def health() -> dict[str, Any]:
        return {
            "ok": True,
            "lane": "python",
            "env_family": MiniHackEngine.ENV_FAMILY,
            "sessions": len(sessions),
        }

    @app.post("/run_scenario")
    def run_scenario_route(body: ScenarioRequest) -> dict[str, Any]:
        return run_scenario(body.task)

    @app.post("/rollouts")
    def create_rollout(body: RolloutRequest) -> dict[str, Any]:
        task = body.task or {
            "schema": "gamebench.task.minihack.v1",
            "task_id": "manual",
            "profile": "corridor_straight",
            "seed": body.seed or 1,
            "rules": {"base": "navigation", "overrides": {"max_steps": 32}},
        }
        engine = MiniHackEngine()
        engine.reset_from_task(task, seed_override=body.seed)
        rollout_id = str(uuid.uuid4())
        sessions[rollout_id] = RolloutSession(rollout_id, engine)
        return _payload(sessions[rollout_id])

    @app.post("/rollouts/{rollout_id}/step")
    def step(rollout_id: str, body: StepRequest) -> dict[str, Any]:
        session = _require(sessions, rollout_id)
        session.engine.step(body.action)
        return _payload(session)

    @app.post("/rollouts/{rollout_id}/checkpoint")
    def checkpoint(rollout_id: str) -> dict[str, Any]:
        session = _require(sessions, rollout_id)
        blob = session.engine.checkpoint_bytes()
        checkpoint_id = str(uuid.uuid4())
        session.checkpoints[checkpoint_id] = blob
        return {
            "rollout_id": rollout_id,
            "checkpoint_id": checkpoint_id,
            "blob": base64.b64encode(blob).decode("ascii"),
            "bytes": len(blob),
            "nev_cursor": session.engine.nev.cursor(),
        }

    @app.post("/rollouts/{rollout_id}/restore")
    def restore(rollout_id: str, body: RestoreRequest) -> dict[str, Any]:
        session = _require(sessions, rollout_id)
        blob = base64.b64decode(body.blob.encode("ascii"))
        restored = session.engine.restore_checkpoint(blob)
        return {
            "rollout_id": rollout_id,
            "restore_report": RestoreReport(bytes=len(blob), wall_ms=0.0, nev_events_restored=restored).to_dict(),
            "readout": session.engine.symbolic_readout(),
        }

    @app.post("/rollouts/{rollout_id}/simulate")
    def simulate(rollout_id: str, body: SimulateRequest) -> dict[str, Any]:
        session = _require(sessions, rollout_id)
        root_blob = base64.b64decode(body.blob.encode("ascii"))
        results: list[dict[str, Any]] = []
        for index, sequence in enumerate(body.sequences):
            sim = session.engine.clone_for_sim()
            sim.restore_checkpoint(root_blob)
            for action in sequence:
                if sim.private.terminated or sim.private.truncated:
                    break
                sim.step(action)
            results.append(
                {
                    "index": index,
                    "actions": sequence,
                    "reward": sim.private.total_reward,
                    "terminated": sim.private.terminated,
                    "truncated": sim.private.truncated,
                    "readout": sim.symbolic_readout(),
                    "nev_cursor": sim.nev.cursor(),
                }
            )
        return {
            "rollout_id": rollout_id,
            "root_nev_cursor": session.engine.nev.cursor(),
            "results": results,
        }

    @app.get("/rollouts/{rollout_id}/readout")
    def readout(rollout_id: str) -> dict[str, Any]:
        return _require(sessions, rollout_id).engine.symbolic_readout()

    @app.get("/rollouts/{rollout_id}/event_log")
    def event_log(rollout_id: str) -> dict[str, Any]:
        engine = _require(sessions, rollout_id).engine
        return {"events": engine.nev.export(), "legacy": engine.nev.legacy_strings(), "nev_cursor": engine.nev.cursor()}

    return app


def _require(sessions: dict[str, RolloutSession], rollout_id: str) -> RolloutSession:
    session = sessions.get(rollout_id)
    if session is None:
        raise HTTPException(status_code=404, detail="rollout not found")
    return session


def _payload(session: RolloutSession) -> dict[str, Any]:
    engine = session.engine
    return {
        "rollout_id": session.rollout_id,
        "readout": engine.symbolic_readout(),
        "reward": engine.private.total_reward,
        "terminated": engine.private.terminated,
        "truncated": engine.private.truncated,
        "nev_cursor": engine.nev.cursor(),
    }


app = create_app()

