#[derive(Clone, Debug)]
struct ResolvedTask {
    task_id: String,
    episode_id: String,
    seed: i64,
    profile: String,
    width: usize,
    height: usize,
    walls: HashSet<(usize, usize)>,
    goals: HashSet<(usize, usize)>,
    targets: HashSet<(usize, usize)>,
    player_start: (usize, usize),
    boulders_start: HashSet<(usize, usize)>,
    monsters_start: HashSet<(usize, usize)>,
    lava_start: HashSet<(usize, usize)>,
    frozen_start: HashSet<(usize, usize)>,
    items_start: HashMap<(usize, usize), String>,
    rules: serde_json::Value,
    max_steps: i64,
    win_mode: String,
    config_hash: String,
}

fn resolve_from_scenario(scenario: &serde_json::Value) -> ResolvedTask {
    let scenario_id = scenario["scenario_id"].as_str().unwrap_or("unknown");
    let task_id = scenario["task_id"].as_str().unwrap_or(scenario_id);
    let seed = scenario["seed"].as_i64().unwrap_or(0);
    let profile = scenario["profile"].as_str().unwrap_or("");
    let rules = scenario.get("rules").cloned().unwrap_or_else(|| serde_json::json!({"base": "navigation"}));
    let max_steps = rules.get("overrides").and_then(|o| o.get("max_steps")).and_then(|m| m.as_i64()).unwrap_or(100);
    let win_mode = rules.get("overrides").and_then(|o| o.get("win_mode")).and_then(|m| m.as_str()).unwrap_or("reach_goal").to_string();

    let mut map_lines = Vec::new();
    if let Some(map) = scenario.get("map") {
        if let Some(arr) = map.as_array() {
            for v in arr {
                if let Some(s) = v.as_str() {
                    map_lines.push(s.to_string());
                }
            }
        }
    } else {
        let lines = get_profile_map(profile);
        for l in lines {
            map_lines.push(l.to_string());
        }
    }

    let height = map_lines.len();
    let mut width = 0;

    let mut walls = HashSet::new();
    let mut goals = HashSet::new();
    let mut targets = HashSet::new();
    let mut player_start = (0, 0);
    let mut boulders_start = HashSet::new();
    let mut monsters_start = HashSet::new();
    let mut lava_start = HashSet::new();
    let mut items_start = HashMap::new();

    for (r, line) in map_lines.iter().enumerate() {
        if line.len() > width { width = line.len(); }
        for (c, ch) in line.chars().enumerate() {
            match ch {
                '#' => { walls.insert((r, c)); },
                '>' => { goals.insert((r, c)); },
                '@' => { player_start = (r, c); },
                '$' => { boulders_start.insert((r, c)); },
                '%' => { targets.insert((r, c)); },
                '*' => { targets.insert((r, c)); boulders_start.insert((r, c)); },
                '+' => { targets.insert((r, c)); player_start = (r, c); },
                'M' => { monsters_start.insert((r, c)); },
                '~' => { lava_start.insert((r, c)); },
                'L' => { items_start.insert((r, c), "levitation".to_string()); },
                'F' => { items_start.insert((r, c), "freeze".to_string()); },
                _ => {}
            }
        }
    }

    let config_hash = get_hash(scenario_id).to_string();
    let episode_id = format!("{}_{}", scenario_id, seed); // or just random? wait, python uses episode_id=scenario_id? No, resolving task might generate a hash.
    // wait, train_eventlogs uses episode_id in events. BUT check.py checks legacy_strings()! 
    // legacy_strings() ONLY use event.message!
    // So episode_id doesn't matter for the output of `events` array!

    ResolvedTask {
        task_id: task_id.to_string(),
        episode_id: "ep".to_string(),
        seed,
        profile: profile.to_string(),
        width,
        height,
        walls,
        goals,
        targets,
        player_start,
        boulders_start,
        monsters_start,
        lava_start,
        frozen_start: HashSet::new(),
        items_start,
        rules,
        max_steps,
        win_mode,
        config_hash,
    }
}

fn direction_delta(direction: &str) -> Option<(isize, isize)> {
    match direction {
        "north" => Some((-1, 0)),
        "south" => Some((1, 0)),
        "east" => Some((0, 1)),
        "west" => Some((0, -1)),
        "northeast" => Some((-1, 1)),
        "northwest" => Some((-1, -1)),
        "southeast" => Some((1, 1)),
        "southwest" => Some((1, -1)),
        _ => None,
    }
}

#[derive(Clone)]
struct MiniHackEngine {
    resolved: ResolvedTask,
    player: (usize, usize),
    walls: HashSet<(usize, usize)>,
    goals: HashSet<(usize, usize)>,
    targets: HashSet<(usize, usize)>,
    boulders: HashSet<(usize, usize)>,
    monsters: HashSet<(usize, usize)>,
    lava: HashSet<(usize, usize)>,
    frozen: HashSet<(usize, usize)>,
    items_on_ground: HashMap<(usize, usize), String>,
    inventory: HashSet<String>,
    step_index: i64,
    total_reward: f64,
    terminated: bool,
    truncated: bool,
    events: Vec<String>,
}

impl MiniHackEngine {
    fn new(resolved: ResolvedTask) -> Self {
        let mut e = Self {
            player: resolved.player_start,
            walls: resolved.walls.clone(),
            goals: resolved.goals.clone(),
            targets: resolved.targets.clone(),
            boulders: resolved.boulders_start.clone(),
            monsters: resolved.monsters_start.clone(),
            lava: resolved.lava_start.clone(),
            frozen: resolved.frozen_start.clone(),
            items_on_ground: resolved.items_start.clone(),
            inventory: HashSet::new(),
            step_index: 0,
            total_reward: 0.0,
            terminated: false,
            truncated: false,
            events: Vec::new(),
            resolved: resolved.clone(),
        };
        e.events.push(format!("TaskResolved({},{})", resolved.task_id, resolved.config_hash));
        e
    }

    fn is_wall(&self, r: usize, c: usize) -> bool {
        self.walls.contains(&(r, c))
    }

    fn is_lava_blocked(&self, r: usize, c: usize) -> bool {
        let pos = (r, c);
        if self.frozen.contains(&pos) { return false; }
        if !self.lava.contains(&pos) { return false; }
        !self.inventory.contains("levitation")
    }

    fn boulders_on_target(&self) -> usize {
        self.boulders.iter().filter(|p| self.targets.contains(p)).count()
    }

    fn step_reward(&self) -> f64 {
        self.resolved.rules.get("overrides").and_then(|o| o.get("step_penalty")).and_then(|v| v.as_f64()).unwrap_or(-0.01)
    }

    fn apply_reward(&mut self, reward: f64) {
        self.total_reward += reward;
        self.events.push(format!("RewardDelta({:.2},total={:.2})", reward, self.total_reward));
    }

    fn terminate_success(&mut self, win_reward: f64, message: &str) {
        self.terminated = true;
        self.events.push(message.to_string());
        self.apply_reward(win_reward);
        self.events.push("Terminal(success)".to_string());
    }

    fn check_win(&mut self) -> bool {
        if self.resolved.win_mode == "reach_goal" {
            if !self.goals.contains(&self.player) { return false; }
            let r = self.resolved.rules.get("overrides").and_then(|o| o.get("goal_reward")).and_then(|v| v.as_f64()).unwrap_or(1.0);
            self.terminate_success(r, &format!("GoalReached(player=[{}, {}])", self.player.0, self.player.1));
            return true;
        }
        if self.resolved.win_mode == "all_boulders_on_targets" {
            let bot = self.boulders_on_target();
            if self.targets.is_empty() || bot != self.targets.len() { return false; }
            let r = self.resolved.rules.get("overrides").and_then(|o| o.get("complete_reward")).and_then(|v| v.as_f64()).unwrap_or(1.0);
            self.terminate_success(r, &format!("LevelComplete(boxoban,count={})", bot));
            return true;
        }
        false
    }

    fn maybe_truncated(&mut self) {
        if self.step_index >= self.resolved.max_steps && !self.terminated {
            self.truncated = true;
            self.events.push("Terminal(truncated)".to_string());
        }
    }

    fn finalize_step(&mut self) {
        if self.check_win() { return; }
        self.maybe_truncated();
    }

    fn blocked(&mut self, code: &str, reward: Option<f64>) {
        if let Some(r) = reward {
            self.apply_reward(r);
        }
        let kind = if code == "box_blocked" { "push_blocked" } else { "move_blocked" };
        self.events.push(format!("{}({})", kind, code));
    }

    fn step_wait(&mut self) {
        let r = self.step_reward();
        self.apply_reward(r);
        self.events.push(format!("ActionApplied(wait,step={})", self.step_index));
        self.finalize_step();
    }

    fn step_pickup(&mut self) {
        let mut reward = self.step_reward();
        if let Some(item_id) = self.items_on_ground.remove(&self.player) {
            self.inventory.insert(item_id.clone());
            if item_id == "freeze" {
                if !self.lava.is_empty() {
                    for l in &self.lava {
                        self.frozen.insert(*l);
                    }
                    self.lava.clear();
                    self.events.push("LavaFrozen(all)".to_string());
                }
            }
            self.events.push(format!("ItemPicked({})", item_id));
            reward += 0.05;
            self.apply_reward(reward);
            self.finalize_step();
        } else {
            self.blocked("no_item", Some(reward));
        }
    }

    fn step_attack(&mut self, direction: &str) {
        let mut reward = self.step_reward();
        if let Some((dr, dc)) = direction_delta(direction) {
            let tr = (self.player.0 as isize + dr) as usize;
            let tc = (self.player.1 as isize + dc) as usize;
            if self.monsters.contains(&(tr, tc)) {
                self.monsters.remove(&(tr, tc));
                self.events.push(format!("MonsterDefeated([{}, {}])", tr, tc));
                reward += 0.2;
                self.apply_reward(reward);
                self.finalize_step();
            } else {
                self.blocked("no_monster", Some(reward));
            }
        } else {
            self.blocked("unknown_direction", None); // python code says no reward applied before direction check
        }
    }

    fn step_move(&mut self, direction: &str) {
        if let Some((dr, dc)) = direction_delta(direction) {
            let mut reward = self.step_reward();
            let nr = (self.player.0 as isize + dr) as usize;
            let nc = (self.player.1 as isize + dc) as usize;

            if self.is_wall(nr, nc) {
                self.blocked("wall", Some(reward));
                return;
            }
            if self.monsters.contains(&(nr, nc)) {
                self.blocked("monster", Some(reward));
                return;
            }
            if self.is_lava_blocked(nr, nc) {
                self.blocked("lava", Some(reward));
                return;
            }

            let mut pushed = false;
            if self.boulders.contains(&(nr, nc)) {
                let br = (nr as isize + dr) as usize;
                let bc = (nc as isize + dc) as usize;
                if self.is_wall(br, bc) || self.boulders.contains(&(br, bc)) || self.monsters.contains(&(br, bc)) {
                    self.blocked("box_blocked", Some(reward));
                    return;
                }
                if self.is_lava_blocked(br, bc) {
                    self.blocked("box_blocked", Some(reward)); // python engine says code="box_blocked", message="push blocked by lava"
                    return;
                }
                self.boulders.remove(&(nr, nc));
                self.boulders.insert((br, bc));
                pushed = true;
                reward += 0.1;
            }

            self.player = (nr, nc);
            self.events.push(format!("ActionApplied({},step={})", direction, self.step_index));
            if pushed {
                let bot = self.boulders_on_target();
                self.events.push(format!("PushApplied({},boulders_on_target={})", direction, bot));
                if bot > 0 {
                    self.events.push(format!("BoulderOnTarget(count={})", bot));
                }
            }
            self.apply_reward(reward);
            self.finalize_step();

        } else {
            self.blocked("unknown_direction", None);
        }
    }

    fn step(&mut self, action: &serde_json::Value) {
        self.step_index += 1;
        if self.terminated || self.truncated {
            self.blocked("terminal", None); // wait, engine.py returns without reward for terminal
            return;
        }

        let kind = action.get("kind").and_then(|v| v.as_str()).unwrap_or("");
        if kind == "wait" {
            self.step_wait();
        } else if kind == "pickup" {
            self.step_pickup();
        } else if kind == "attack" {
            let dir = action.get("direction").and_then(|v| v.as_str()).unwrap_or("");
            self.step_attack(dir);
        } else if kind == "move" {
            let dir = action.get("direction").and_then(|v| v.as_str()).unwrap_or("");
            self.step_move(dir);
        } else {
            self.blocked("unknown_action", None);
        }
    }
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let scenario: serde_json::Value = serde_json::from_str(&input).unwrap();

    let resolved = resolve_from_scenario(&scenario);
